"""Targets v4: o' generated by gpt-4o-mini; one target per distinct gold passage; no rare/common strata.

Why: v2/v3 picked o' from objects seen with the same relation, and most of those swaps were implausible
(v3 kept 32 of 158 at plausibility >= 4). v4 asks for plausible replacements directly.

Pipeline
  1. Anchors (offline, unchanged rule): exactly one answer-object triple (s, r, o) across the supporting passages,
     s and o verbatim, o not in the title, o not inside another entity of the passage's triples.
  2. Single-valued filter (offline): drop if the subject has >= 2 distinct objects for the relation in the corpus.
  3. One question per gold passage (seeded choice when several questions share it). Unit of analysis = distinct swap.
  4. Generation (paid, own cache): one call per passage; JSON reply with 3 replacements for o of the same fine-grained
     type, plausible to an informed reader in this exact sentence, and false. The first candidate passing the offline
     checks is used: not o, not an answer alias, no substring either way, not in the question's own paragraphs,
     same surface shape (digit / capitalised / leading article), non-empty, no doubled token at the swap boundary.
  5. Plausibility (paid, own cache): the v3 rater on the swapped sentence; keep 4-5.
  6. Cap at 120 (seeded), then collision-free groups (v3 greedy colouring).
Frequency of o and o' (corpus passages whose triples contain the entity; 0 if absent) is logged as a covariate.
Triples are copied from the OpenIE cache with o replaced, never extracted. A generated o' absent from the corpus
becomes a new entity node at indexing time (its vector comes from the embed-once table).

    .venv/bin/python experiments/extension/select_targets_v4.py --estimate
    .venv/bin/python experiments/extension/select_targets_v4.py --confirm-paid       # runs only if estimate < --max_inr
"""
import argparse
import collections
import json
import random
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from experiments.extension.common import (BASE_OPENIE_STATE, DATA_DIR, DATASET_DIR, PRICE_USD_PER_M, REPO_ROOT,  # noqa: E402
                                          chunk_text, contains_phrase, inr, text_processing as tp)
from experiments.extension.select_targets import (_has_shape, build_corpus_index, find_anchor, make_target,  # noqa: E402
                                                  sentence_with)
from experiments.extension.select_targets_v2 import subject_relation_objects  # noqa: E402
from experiments.extension.select_targets_v3 import (KEEP_MIN_SCORE, assign_groups, check_groups,  # noqa: E402
                                                     doubled_token_hits, parse_score, plausibility_messages, swapped_sentence)

TARGETS_V4_PATH = DATA_DIR / "targets_v4.jsonl"
REVIEW_V4_PATH = DATA_DIR / "review_v4.md"
GEN_CACHE = REPO_ROOT / "outputs" / "extension" / "target_generation_v4" / "llm_cache"
RATE_CACHE = REPO_ROOT / "outputs" / "extension" / "target_plausibility_v4" / "llm_cache"
GEN_MAX_TOKENS = 100
RATE_MAX_TOKENS = 8
N_CAP = 120

GEN_SYSTEM = "You help build a counterfactual test set of plausible but false sentences."


# ------------------------------------------------------------------ 1-3 offline ------------------------
def anchors_one_per_passage(samples, openie_docs, seed=0):
    """[(q_index, sample, para, t_index, triple)] with one question per gold passage, plus rejection counts."""
    by_passage, _, _ = build_corpus_index(openie_docs)
    sro = subject_relation_objects(openie_docs)
    reasons = collections.Counter()
    by_gold = collections.defaultdict(list)
    for q_index, sample in enumerate(samples):
        para, t_index, triple, reason = find_anchor(sample, by_passage)
        if reason:
            reasons[reason] += 1
            continue
        s, r, o = triple
        if len(sro[(tp(s), tp(r))]) >= 2:
            reasons["multi-valued in corpus (subject has >= 2 objects for the relation)"] += 1
            continue
        by_gold[chunk_text(para["title"], para["paragraph_text"])].append((q_index, sample, para, t_index, triple))
    rng = random.Random(seed)
    chosen = []
    for gold in sorted(by_gold):
        options = by_gold[gold]
        if len(options) > 1:
            reasons["another question on the same gold passage (one kept per passage)"] += len(options) - 1
        chosen.append(rng.choice(options))
    return chosen, reasons


# ------------------------------------------------------------------ 4 generation -----------------------
def generation_messages(sentence, s, r, o):
    user = (f"Sentence: {sentence}\n"
            f"Fact in the sentence: ({s} | {r} | {o})\n\n"
            f"Propose 3 different replacements for \"{o}\". Each replacement must:\n"
            f"- be the same fine-grained type as \"{o}\" (a full date for a full date, a year for a year, a county for a "
            f"county, a person for a person, a record label for a record label);\n"
            f"- keep this exact sentence plausible to an informed reader (right era, nationality, region and category);\n"
            f"- make the sentence false.\n"
            f"Do not propose \"{o}\" itself, an alias or spelling variant of it, or anything that contains it.\n\n"
            "Reply with JSON only: {\"candidates\": [\"...\", \"...\", \"...\"]}")
    return [{"role": "system", "content": GEN_SYSTEM}, {"role": "user", "content": user}]


def parse_candidates(text):
    m = re.search(r"\{.*\}", text, re.S)
    if not m:
        return []
    try:
        cands = json.loads(m.group(0)).get("candidates", [])
    except (json.JSONDecodeError, AttributeError):
        return []
    return [c.strip() for c in cands if isinstance(c, str) and c.strip()]


def check_candidate(cand, sample, para, triple):
    """None if the candidate passes every offline check, else the first failing check's name."""
    s, r, o = triple
    answers = {tp(a) for a in [sample["answer"]] + list(sample.get("answer_aliases", []))}
    nc, no = tp(cand), tp(o)
    if not nc or len(re.sub(r"[^0-9a-z]", "", nc)) < 2:
        return "empty"
    if nc == no:
        return "equals o"
    if nc in answers:
        return "answer alias"
    if no in nc or nc in no:
        return "substring of/contains o"
    if nc == tp(s):
        return "equals s"
    if _has_shape(cand) != _has_shape(o):
        return "surface shape differs"
    if any(contains_phrase(chunk_text(p["title"], p["paragraph_text"]), cand, ignore_case=True) for p in sample["paragraphs"]):
        return "in the question's own paragraphs"
    if doubled_token_hits(para["paragraph_text"], o, cand):
        return "doubled token"
    return None


# ------------------------------------------------------------------ outputs ----------------------------
def review_markdown(targets):
    def cell(x):
        return str(x).replace("|", "\\|").replace("\n", " ")
    rows = sorted(targets, key=lambda t: (t["plausibility"], t["target_id"]))
    lines = ["# Targets v4 review", "",
             f"{len(targets)} targets = {len(targets)} distinct gold passages / swaps (lowest plausibility first). "
             "o -> o' in bold. freq = corpus passages whose triples contain the entity (0 = absent).", "",
             "| # | target | score | freq o | freq o' | group | original | swapped |", "|---|---|---|---|---|---|---|---|"]
    for i, t in enumerate(rows, 1):
        orig = sentence_with(t["body"], t["o"]).replace(t["o"], f"**{t['o']}**")
        new = swapped_sentence(t).replace(t["o_prime"], f"**{t['o_prime']}**")
        lines.append(f"| {i} | {t['target_id']} | {t['plausibility']} | {t['freq_o_graph']} | {t['freq_oprime_graph']} | "
                     f"{t['group']} | {cell(orig)} | {cell(new)} |")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--estimate", action="store_true")
    mode.add_argument("--confirm-paid", action="store_true")
    parser.add_argument("--max_inr", type=float, default=3.0)
    parser.add_argument("--seed", type=int, default=0)
    args = parser.parse_args()

    samples = json.loads((DATASET_DIR / "musique.json").read_text(encoding="utf-8"))
    openie_docs = json.loads(Path(BASE_OPENIE_STATE).read_text(encoding="utf-8"))["docs"]
    anchors, reasons = anchors_one_per_passage(samples, openie_docs, args.seed)

    import tiktoken
    enc = tiktoken.get_encoding("o200k_base")
    ntok = lambda ms: sum(len(enc.encode(m["content"])) + 4 for m in ms) + 3
    gen_msgs = [generation_messages(sentence_with(para["paragraph_text"], triple[2]), *triple)
                for _, _, para, _, triple in anchors]
    rate_proxy = [plausibility_messages(sentence_with(para["paragraph_text"], triple[2])) for _, _, para, _, triple in anchors]
    tin_gen, tin_rate = sum(map(ntok, gen_msgs)), sum(map(ntok, rate_proxy))
    usd = ((tin_gen + tin_rate) * PRICE_USD_PER_M["gpt-4o-mini_in"]
           + len(anchors) * (GEN_MAX_TOKENS + RATE_MAX_TOKENS) * PRICE_USD_PER_M["gpt-4o-mini_out"]) / 1e6
    print(json.dumps({"distinct_passages": len(anchors), "offline_rejections": dict(reasons),
                      "generation_calls": len(anchors), "generation_tokens_in": tin_gen,
                      "rating_calls_max": len(anchors), "rating_tokens_in_approx": tin_rate,
                      "output_tokens_max": len(anchors) * (GEN_MAX_TOKENS + RATE_MAX_TOKENS),
                      "estimate_inr_upper": round(inr(usd), 3)}, indent=1))
    if args.estimate:
        print("\nexample generation prompt:\n" + gen_msgs[0][1]["content"])
        return
    if inr(usd) >= args.max_inr:
        sys.exit(f"estimate Rs {inr(usd):.2f} is not under Rs {args.max_inr}; not running")

    from experiments.extension.common import capture_config
    from src.hipporag.llm.openai_gpt import CacheOpenAI
    config = capture_config("/nonexistent/target_v4")
    gen = CacheOpenAI(cache_dir=str(GEN_CACHE), global_config=config)
    rate = CacheOpenAI(cache_dir=str(RATE_CACHE), global_config=config)
    index = build_corpus_index(openie_docs)
    all_passages = list(index[0])
    usage = collections.Counter()

    def call(llm, msgs, max_tokens, kind):
        text, meta, hit = llm.infer(msgs, max_new_tokens=max_tokens)
        usage[f"{kind}_calls"] += 1
        usage[f"{kind}_cache_hits"] += int(bool(hit))
        if not hit:
            usage["prompt_tokens"] += meta.get("prompt_tokens", 0)
            usage["completion_tokens"] += meta.get("completion_tokens", 0)
        return text

    funnel = collections.Counter(distinct_passages=len(anchors))
    log, rated = [], []
    for (q_index, sample, para, t_index, triple), msgs in zip(anchors, gen_msgs):
        text = call(gen, msgs, GEN_MAX_TOKENS, "generation")
        cands = parse_candidates(text)
        checks = [(c, check_candidate(c, sample, para, triple)) for c in cands]
        entry = {"target_id": sample["id"], "o": triple[2], "response": text, "checks": checks}
        log.append(entry)
        chosen = next((c for c, fail in checks if fail is None), None)
        if not cands:
            funnel["generation unparseable"] += 1
            continue
        if chosen is None:
            funnel["no candidate passed offline checks"] += 1
            continue
        funnel["candidate passed offline checks"] += 1
        t = make_target(index, all_passages, q_index, sample, para, t_index, triple, chosen, None)
        t.pop("stratum")
        t.update(o_prime_source="gpt-4o-mini generated", o_prime_rank=[c for c, _ in checks].index(chosen) + 1,
                 o_prime_candidates=cands)
        score_text = call(rate, plausibility_messages(swapped_sentence(t)), RATE_MAX_TOKENS, "rating")
        t["plausibility"], t["plausibility_response"] = parse_score(score_text), score_text
        entry.update(o_prime=chosen, plausibility=t["plausibility"])
        rated.append(t)
    gen.close()
    rate.close()

    kept = [t for t in rated if t["plausibility"] is not None and t["plausibility"] >= KEEP_MIN_SCORE]
    funnel[f"plausibility >= {KEEP_MIN_SCORE}"] = len(kept)
    if len(kept) > N_CAP:
        kept = random.Random(args.seed).sample(kept, N_CAP)
    funnel["after cap"] = len(kept)
    n_groups = assign_groups(kept)
    check_groups(kept)
    with open(TARGETS_V4_PATH, "w", encoding="utf-8") as f:
        for t in sorted(kept, key=lambda t: (t["group"], t["target_id"])):
            f.write(json.dumps(t, ensure_ascii=False) + "\n")
    REVIEW_V4_PATH.write_text(review_markdown(kept), encoding="utf-8")
    GEN_CACHE.parent.joinpath("generations.json").write_text(json.dumps(log, ensure_ascii=False, indent=1), encoding="utf-8")

    fail_counts = collections.Counter(fail for e in log for _, fail in e["checks"] if fail)
    usd_actual = (usage["prompt_tokens"] * PRICE_USD_PER_M["gpt-4o-mini_in"]
                  + usage["completion_tokens"] * PRICE_USD_PER_M["gpt-4o-mini_out"]) / 1e6
    freq_bins = lambda f: "0" if f == 0 else ("1-9" if f < 10 else ">=10")
    print(json.dumps({
        "funnel": dict(funnel), "candidate_check_failures": dict(fail_counts),
        "chosen_rank": dict(collections.Counter(t["o_prime_rank"] for t in rated)),
        "score_hist_all_rated": dict(sorted(collections.Counter(t["plausibility"] for t in rated).items(), key=str)),
        "kept": len(kept), "groups": n_groups,
        "group_sizes": dict(sorted(collections.Counter(t["group"] for t in kept).items())),
        "freq_oprime_bins": dict(collections.Counter(freq_bins(t["freq_oprime_graph"]) for t in kept)),
        "freq_o_bins": dict(collections.Counter(freq_bins(t["freq_o_graph"]) for t in kept)),
        "usage": dict(usage), "actual_inr": round(inr(usd_actual), 3)}, indent=1))
    print(f"wrote {TARGETS_V4_PATH} and {REVIEW_V4_PATH}")


if __name__ == "__main__":
    main()
